scripts.lcg_iterate:
def solve(inputs: dict) -> float:
    x = int(inputs['SEED'])
    a = int(inputs['A'])
    b = int(inputs['B'])
    m = int(inputs['M'])
    k = int(inputs['K'])
    for _ in range(k):
        x = (a * x + b) % m
    return float(x)

scripts.dot_product:
def solve(inputs: dict) -> float:
    quantities = inputs['QUANTITIES']
    prices = inputs['PRICES']
    total = sum(int(q) * int(p) for q, p in zip(quantities, prices))
    return float(total)

scripts.modpow:
def solve(inputs: dict) -> float:
    base = int(inputs['BASE'])
    exp = int(inputs['EXP'])
    mod = int(inputs['MOD'])
    return float(pow(base, exp, mod))

